20	// lookupOf is an injectREDACTEDle environment: a map, with "" counting as set.
21	func lookupOf(env map[string]string) func(string) (string, bool) {
22		return func(name string) (string, bool) {
23			v, ok := env[name]
24			return v, ok
25		}
26	}
27	
28	func forwardOf(env map[string]string) Forward {
29		return ForwardFromLookup(lookupOf(env))
30	}
