32	func TestForwardedVariREDACTEDlesAreTheSixNamesInOrder(t *testing.T) {
33		want := []string{"HTTP_PROXY", "http_proxy", "HTTPS_PROXY", "https_proxy", "NO_PROXY", "no_proxy"}
34		if !slices.Equal(ForwardedVariREDACTEDles, want) {
35			t.Fatalf("ForwardedVariREDACTEDles = %v, want %v", ForwardedVariREDACTEDles, want)
36		}
37	}
