39	func TestForwardZeroValueIsEmptyAndSafe(t *testing.T) {
40		var f Forward
41		if !f.Empty() {
42			t.Error("the zero Forward is not Empty()")
43		}
44		if got := f.Names(); len(got) != 0 {
45			t.Errorf("Names() = %v, want none", got)
46		}
47		if got := f.Redact("nothing to hide"); got != "nothing to hide" {
48			t.Errorf("Redact changed a text with no REDACTED: %q", got)
49		}
50		if _, _, ok := f.Loopback(); ok {
51			t.Error("the zero Forward reports a loopback proxy")
52		}
53		_ = f.String() // must not panic
54	}
