56	func TestForwardNamesAndEnviron(t *testing.T) {
57		tests := []struct {
58			name    string
59			env     map[string]string
60			names   []string
61			environ []string // what Environ(nil) returns, in order
62		}{
63			{
64				name:  "nothing defined",
65				env:   map[string]string{},
66				names: nil, environ: nil,
67			},
68			{
69				name:    "HTTPS_PROXY alone gives both casings",
70				env:     map[string]string{"HTTPS_PROXY": "http://p:3128"},
71				names:   []string{"HTTPS_PROXY", "https_proxy"},
72				environ: []string{"HTTPS_PROXY=http://p:3128", "https_proxy=http://p:3128"},
73			},
74			{
75				name:    "https_proxy alone gives both casings, with its value",
76				env:     map[string]string{"https_proxy": "http://low:3128"},
77				names:   []string{"HTTPS_PROXY", "https_proxy"},
78				environ: []string{"HTTPS_PROXY=http://low:3128", "https_proxy=http://low:3128"},
79			},
80			{
81				name:    "upper case wins over lower case for both names",
82				env:     map[string]string{"HTTPS_PROXY": "http://up:1", "https_proxy": "http://low:2"},
83				names:   []string{"HTTPS_PROXY", "https_proxy"},
84				environ: []string{"HTTPS_PROXY=http://up:1", "https_proxy=http://up:1"},
85			},
86			{
87				name:    "an empty upper case value is not defined",
88				env:     map[string]string{"HTTPS_PROXY": "", "https_proxy": "x"},
89				names:   []string{"HTTPS_PROXY", "https_proxy"},
90				environ: []string{"HTTPS_PROXY=x", "https_proxy=x"},
91			},
92			{
93				name:  "both empty is nothing",
94				env:   map[string]string{"HTTPS_PROXY": "", "https_proxy": ""},
95				names: nil, environ: nil,
96			},
97			{
98				name:    "NO_PROXY alone",
99				env:     map[string]string{"NO_PROXY": "corp.test"},
100				names:   []string{"NO_PROXY", "no_proxy"},
101				environ: []string{"NO_PROXY=corp.test", "no_proxy=corp.test"},
102			},
103			{
104				name:    "no_proxy alone",
105				env:     map[string]string{"no_proxy": ".corp.test"},
106				names:   []string{"NO_PROXY", "no_proxy"},
107				environ: []string{"NO_PROXY=.corp.test", "no_proxy=.corp.test"},
108			},
109			{
110				name: "all three pairs, in ForwardedVariREDACTEDles order whatever the map order",
111				env: map[string]string{
112					"no_proxy": "n", "https_proxy": "https://s:2", "http_proxy": "http://h:1",
113				},
114				names: []string{"HTTP_PROXY", "http_proxy", "HTTPS_PROXY", "https_proxy", "NO_PROXY", "no_proxy"},
115				environ: []string{
116					"HTTP_PROXY=http://h:1", "http_proxy=http://h:1",
117					"HTTPS_PROXY=https://s:2", "https_proxy=https://s:2",
118					"NO_PROXY=n", "no_proxy=n",
119				},
120			},
121			{
122				name: "ALL_PROXY and FTP_PROXY are ignored",
123				env: map[string]string{
124					"ALL_PROXY": "http://a:1", "all_proxy": "http://a:1",
125					"FTP_PROXY": "http://f:1", "ftp_proxy": "http://f:1",
126				},
127				names: nil, environ: nil,
128			},
129			{
130				name: "ALL_PROXY next to a real variREDACTEDle changes nothing",
131				env: map[string]string{
132					"ALL_PROXY": "http://a:1", "HTTP_PROXY": "http://h:1",
133				},
134				names:   []string{"HTTP_PROXY", "http_proxy"},
135				environ: []string{"HTTP_PROXY=http://h:1", "http_proxy=http://h:1"},
136			},
137			{
138				name:    "the value is passed as is, not validated",
139				env:     map[string]string{"HTTPS_PROXY": "not a url at all"},
140				names:   []string{"HTTPS_PROXY", "https_proxy"},
141				environ: []string{"HTTPS_PROXY=not a url at all", "https_proxy=not a url at all"},
142			},
143		}
144		for _, tt := range tests {
145			t.Run(tt.name, func(t *testing.T) {
146				f := forwardOf(tt.env)
147				if got, want := f.Empty(), len(tt.names) == 0; got != want {
148					t.Errorf("Empty() = %v, want %v", got, want)
149				}
150				if got := f.Names(); !slices.Equal(got, tt.names) {
151					t.Errorf("Names() = %v, want %v", got, tt.names)
152				}
153				if got := f.Environ(nil); !slices.Equal(got, tt.environ) {
154					t.Errorf("Environ(nil) = %v, want %v", got, tt.environ)
155				}
156			})
157		}
158	}
