160	func TestForwardEnvironWithNothingToForwardReturnsBase(t *testing.T) {
161		base := []string{"PATH=/bin", "HOME=/h"}
162		got := forwardOf(nil).Environ(base)
163		if !slices.Equal(got, base) {
164			t.Errorf("Environ(base) = %v, want %v", got, base)
165		}
