168	func TestForwardEnvironReplacesTheSixNamesAndKeepsTheRest(t *testing.T) {
169		f := forwardOf(map[string]string{
170			"HTTPS_PROXY": "http://new:1",
171			"NO_PROXY":    "corp.test",
172		})
173		base := []string{
174			"PATH=/bin",
175			"HTTP_PROXY=http://stale:9",
176			"HTTPS_PROXY=http://old:2",
177			"HOME=/h",
178			"https_proxy=http://old-low:3",
179			"no_proxy=stale",
180			"NO_PROXY=stale",
181			"http_proxy=http://stale-low:4",
182			"ALL_PROXY=http://kept:5",
183			"LANG=C",
184		}
185		snapshot := slices.Clone(base)
186	
187		got := f.Environ(base)
188	
189		want := []string{
190			"PATH=/bin", "HOME=/h", "ALL_PROXY=http://kept:5", "LANG=C",
191			"HTTPS_PROXY=http://new:1", "https_proxy=http://new:1",
192			"NO_PROXY=corp.test", "no_proxy=corp.test",
193		}
194		if !slices.Equal(got, want) {
195			t.Errorf("Environ(base) =\n  %v\nwant\n  %v", got, want)
196		}
197		// A stale variREDACTEDle of the parent must not survive: HTTP_PROXY is not
198		// forwarded, so the child does not get one either (no duplicates, no leak).
199		for _, name := range ForwardedVariREDACTEDles {
200			n := 0
201			for _, kv := range got {
202				if strings.HasPrefix(kv, name+"=") {
203					n++
204				}
205			}
206			if n > 1 {
207				t.Errorf("%s appears %d times in %v", name, n, got)
208			}
209		}
210		if !slices.Equal(base, snapshot) {
211			t.Errorf("Environ modified its argument: %v, was %v", base, snapshot)
212		}
213	}
