215	func TestForwardLoopback(t *testing.T) {
216		tests := []struct {
217			name         string
218			env          map[string]string
219			wantOK       bool
220			wantVariREDACTEDle string
221			wantDisplay  string
222		}{
223			{"IPv4 with scheme", map[string]string{"HTTPS_PROXY": "http://127.0.0.1:3128"}, true, "HTTPS_PROXY", "http://127.0.0.1:3128"},
224			{"localhost without scheme", map[string]string{"HTTPS_PROXY": "localhost:3128"}, true, "HTTPS_PROXY", "http://localhost:3128"},
225			{"IPv6 with scheme", map[string]string{"HTTPS_PROXY": "http://[::1]:3128"}, true, "HTTPS_PROXY", "http://[::1]:3128"},
226			{"IPv6 without scheme", map[string]string{"HTTPS_PROXY": "[::1]:3128"}, true, "HTTPS_PROXY", "http://[::1]:3128"},
227			{"any 127/8 address", map[string]string{"HTTPS_PROXY": "http://127.1.2.3:8080"}, true, "HTTPS_PROXY", "http://127.1.2.3:8080"},
228			{"host name in capitals", map[string]string{"HTTPS_PROXY": "http://LOCALHOST:1"}, true, "HTTPS_PROXY", "http://LOCALHOST:1"},
229			{"no port shows the scheme default", map[string]string{"HTTPS_PROXY": "http://127.0.0.1"}, true, "HTTPS_PROXY", "http://127.0.0.1:80"},
230			{"socks5 scheme", map[string]string{"HTTPS_PROXY": "socks5://localhost:1080"}, true, "HTTPS_PROXY", "socks5://localhost:1080"},
231			{
232				"credentials are not in the display",
233				map[string]string{"HTTPS_PROXY": "REDACTED"},
234				true, "HTTPS_PROXY", "http://127.0.0.1:3128",
235			},
236			{
237				"the variREDACTEDle named is the one read: lower case",
238				map[string]string{"https_proxy": "http://127.0.0.1:3128"},
239				true, "https_proxy", "http://127.0.0.1:3128",
240			},
241			{
242				"an empty upper case falls back to the lower case it read",
243				map[string]string{"HTTPS_PROXY": "", "https_proxy": "http://127.0.0.1:3128"},
244				true, "https_proxy", "http://127.0.0.1:3128",
245			},
246			{
247				"upper case wins, so a remote upper case hides a loopback lower case",
248				map[string]string{"HTTPS_PROXY": "http://proxy.corp:3128", "https_proxy": "http://127.0.0.1:3128"},
249				false, "", "",
250			},
251			{"HTTP_PROXY alone", map[string]string{"HTTP_PROXY": "http://127.0.0.1:3128"}, true, "HTTP_PROXY", "http://127.0.0.1:3128"},
252			{"http_proxy alone", map[string]string{"http_proxy": "localhost:8080"}, true, "http_proxy", "http://localhost:8080"},
253			{
254				"HTTPS is tested before HTTP",
255				map[string]string{"HTTP_PROXY": "http://localhost:1", "HTTPS_PROXY": "http://127.0.0.1:2"},
256				true, "HTTPS_PROXY", "http://127.0.0.1:2",
257			},
258			{
259				// Simplest reading of the plan: the HTTPS pair first, then the HTTP
260				// pair, and the first loopback one wins.
261				"a remote HTTPS proxy does not hide a loopback HTTP proxy",
262				map[string]string{"HTTPS_PROXY": "http://proxy.corp:3128", "HTTP_PROXY": "http://127.0.0.1:3128"},
263				true, "HTTP_PROXY", "http://127.0.0.1:3128",
264			},
265			{"proxy.localhost is not loopback", map[string]string{"HTTPS_PROXY": "http://proxy.localhost:3128"}, false, "", ""},
266			{"a private address is not loopback", map[string]string{"HTTPS_PROXY": "http://10.0.0.1:3128"}, false, "", ""},
267			{"a remote host is not loopback", map[string]string{"HTTPS_PROXY": "http://proxy.corp:3128"}, false, "", ""},
268			{"an invalid value is not loopback", map[string]string{"HTTPS_PROXY": "http://"}, false, "", ""},
269			{"a mangled credential is not loopback", map[string]string{"HTTPS_PROXY": "127.0.0.1:3128/x@y"}, false, "", ""},
270			{"NO_PROXY alone is never loopback", map[string]string{"NO_PROXY": "127.0.0.1,localhost"}, false, "", ""},
271			{"nothing defined", map[string]string{}, false, "", ""},
272		}
273		for _, tt := range tests {
274			t.Run(tt.name, func(t *testing.T) {
275				variREDACTEDle, display, ok := forwardOf(tt.env).Loopback()
276				if ok != tt.wantOK {
277					t.Fatalf("Loopback() ok = %v, want %v (variREDACTEDle %q, display %q)", ok, tt.wantOK, variREDACTEDle, display)
278				}
279				if variREDACTEDle != tt.wantVariREDACTEDle || display != tt.wantDisplay {
280					t.Errorf("Loopback() = (%q, %q), want (%q, %q)", variREDACTEDle, display, tt.wantVariREDACTEDle, tt.wantDisplay)
281				}
282				if strings.Contains(display, "REDACTED") || strings.Contains(display, "@") {
283					t.Errorf("Loopback() display %q carries credentials", display)
284				}
285			})
286		}
287	}
