1	package netproxy
2	
3	import (
4		"net/url"
5		"os"
6		"slices"
7		"strings"
8		"sync"
9	)
10	
11	// ForwardedVariables are the variables a container receives, in this order,
12	// each name followed by its other casing. ALL_PROXY and FTP_PROXY are not read.
13	var ForwardedVariables = []string{
14		"HTTP_PROXY", "http_proxy",
15		"HTTPS_PROXY", "https_proxy",
16		"NO_PROXY", "no_proxy",
17	}
18	
19	// redacted stands for a proxy value that could not be parsed, so it has no
20	// display form.
21	const redacted = "[redacted]"
22	
23	// forwardPair is one variable in both casings, with the value they both carry.
24	type forwardPair struct {
25		names [2]string
26		value string
27		// read is the name the value was read from, with the case it had.
28		read string
29	}
30	
31	// Forward is a snapshot of the proxy variables as a child process must receive
32	// them. It holds raw values, credentials included, and never prints them: String
33	// and GoString show the display form. The zero value forwards nothing.
34	type Forward struct {
35		pairs []forwardPair
36	}
37	
38	// containerForward reads the environment once, like http.ProxyFromEnvironment.
39	var containerForward = sync.OnceValue(func() Forward {
40		return ForwardFromLookup(os.LookupEnv)
41	})
42	
43	// ContainerForward is the proxy environment of this process, read once.
44	func ContainerForward() Forward { return containerForward() }
45	
46	// ForwardFromLookup reads the variables through lookup. For each of HTTP, HTTPS
47	// and NO, the first non-empty value of the upper case name then the lower case
48	// name is given to both names. The value is not validated.
49	func ForwardFromLookup(lookup func(string) (string, bool)) Forward {
50		getenv := func(name string) string {
51			v, _ := lookup(name)
52			return v
53		}
54		var f Forward
55		for i := 0; i < len(ForwardedVariables); i += 2 {
56			names := [2]string{ForwardedVariables[i], ForwardedVariables[i+1]}
57			if read, value := firstNonEmpty(names, getenv); read != "" {
58				f.pairs = append(f.pairs, forwardPair{names: names, value: value, read: read})
59			}
60		}
61		return f
62	}
63	
64	// Empty reports whether there is nothing to forward.
65	func (f Forward) Empty() bool { return len(f.pairs) == 0 }
66	
67	// Names lists the variables to pass, in ForwardedVariables order.
68	func (f Forward) Names() []string {
69		var names []string
70		for _, p := range f.pairs {
71			names = append(names, p.names[:]...)
72		}
73		return names
74	}
75	
76	// Environ returns base without any of the six forwarded names, followed by
77	// NAME=value for every name to forward. base is not modified; when there is
78	// nothing to forward it is returned as is.
79	func (f Forward) Environ(base []string) []string {
80		if f.Empty() {
81			return base
82		}
83		env := make([]string, 0, len(base)+len(f.pairs)*2)
84		for _, kv := range base {
85			name, _, _ := strings.Cut(kv, "=")
86			if !slices.Contains(ForwardedVariables, name) {
87				env = append(env, kv)
88			}
89		}
90		for _, p := range f.pairs {
91			for _, name := range p.names {
92				env = append(env, name+"="+p.value)
93			}
94		}
95		return env
96	}
97	
98	// Loopback reports whether a proxy the container would use is on this machine,
99	// where it cannot be reached from inside the container. The HTTPS pair is tried
100	// before the HTTP pair and the first loopback value wins. variable is the name
101	// that was read and display carries no credential.
102	func (f Forward) Loopback() (variable, display string, ok bool) {
103		for _, upper := range []string{"HTTPS_PROXY", "HTTP_PROXY"} {
104			for _, p := range f.pairs {
105				if p.names[0] != upper {
106					continue
107				}
108				if u, usable := parseProxyValue(p.value); usable && isLoopbackHost(u.Hostname()) {
109					return p.read, Display(u), true
110				}
111			}
112		}
113		return "", "", false
114	}
115	
116	// Redact removes every credential held by f from s: a raw proxy value becomes
117	// its display form, and its user:password@ and password forms (decoded and
118	// escaped) disappear. A password shorter than 4 bytes is only removed in the
119	// full value and in user:password@, since replacing it anywhere would damage
120	// the text.
121	func (f Forward) Redact(s string) string {
122		var olds []string
123		var free []string // secrets replaced wherever they appear
124		for _, p := range f.pairs {
125			if p.names[0] == "NO_PROXY" {
126				continue
127			}
128			u, usable := parseProxyValue(p.value)
129			if !usable {
130				olds = append(olds, p.value, redacted)
131				continue
132			}
133			olds = append(olds, p.value, Display(u))
134			if u.User == nil {
135				continue
136			}
137			userinfos, secrets := credentialForms(u.User)
138			// Longer matches first: Replacer tries its arguments in order.
139			for _, userinfo := range userinfos {
140				olds = append(olds, userinfo+"@", "")
141			}
142			for _, secret := range secrets {
143				if len(secret) >= 4 {
144					free = append(free, secret)
145				}
146			}
147		}
148		if len(olds) == 0 {
149			return s
150		}
151		for _, secret := range free {
152			olds = append(olds, secret, redacted)
153		}
154		return strings.NewReplacer(olds...).Replace(s)
155	}
156	
157	// String shows the variables with the proxies in display form, never raw.
158	func (f Forward) String() string {
159		if f.Empty() {
160			return "no proxy variables"
161		}
162		parts := make([]string, 0, len(f.pairs))
163		for _, p := range f.pairs {
164			shown := p.value
165			if p.names[0] != "NO_PROXY" {
166				shown = redacted
167				if u, ok := parseProxyValue(p.value); ok {
168					shown = Display(u)
169				}
170			}
171			parts = append(parts, p.names[0]+"="+shown)
172		}
173		return strings.Join(parts, " ")
174	}
175	
176	// GoString is String, so %#v shows no raw value either.
177	func (f Forward) GoString() string { return f.String() }
178	
179	// credentialForms returns the user:password forms of ui, escaped as in the
180	// URL then decoded, and the secret part (the password, or the user name when
181	// there is no password) in the same two forms.
182	func credentialForms(ui *url.Userinfo) (userinfos, secrets []string) {
183		user := ui.Username()
184		password, hasPassword := ui.Password()
185		escaped := ui.String()
186		if !hasPassword {
187			return []string{escaped, user}, []string{user}
188		}
189		_, escapedPassword, _ := strings.Cut(escaped, ":")
190		return []string{escaped, user + ":" + password}, []string{escapedPassword, password}
191	}
