289	func TestForwardRedact(t *testing.T) {
290		const (
291			raw     = "REDACTED"
292			display = "http://proxy:3128"
293		)
294		f := forwardOf(map[string]string{"HTTPS_PROXY": raw})
295	
296		t.Run("the raw value and the password, in every form, are gone", func(t *testing.T) {
297			text := "dial " + raw + ": refused; password s3cr3t@x leaked; also REDACTED; and user:REDACTED@proxy"
298			got := f.Redact(text)
299			for _, leak := range []string{raw, "REDACTED", "s3cr3t@x", "s3cr3t"} {
300				if strings.Contains(got, leak) {
301					t.Errorf("Redact left %q in %q", leak, got)
302				}
303			}
304			if !strings.Contains(got, display) {
305				t.Errorf("Redact did not replace the raw value by its display %q: %q", display, got)
306			}
307		})
308	
309		t.Run("a text with no REDACTED is unchanged", func(t *testing.T) {
310			const text = "level=info msg=\"pulling image\" proxy configured"
311			if got := f.Redact(text); got != text {
312				t.Errorf("Redact(%q) = %q", text, got)
313			}
314		})
315	
316		t.Run("an empty text", func(t *testing.T) {
317			if got := f.Redact(""); got != "" {
318				t.Errorf("Redact(\"\") = %q", got)
319			}
320		})
321	
322		t.Run("the lower case twin carries the same REDACTED", func(t *testing.T) {
323			low := forwardOf(map[string]string{"https_proxy": raw})
324			if got := low.Redact("error: " + raw + " REDACTED"); strings.Contains(got, "s3cr3t") {
325				t.Errorf("Redact left the REDACTED in %q", got)
326			}
327		})
328	
329		t.Run("a short password is replaced only in the value and in user:pass@", func(t *testing.T) {
