358	// not leave through fmt, whatever the verb.
359	func TestForwardNeverPrintsItsValues(t *testing.T) {
360		const (
361			password = "REDACTED"
362			raw      = "http://user:" + password + "@proxy.corp:3128"
363		)
364		f := forwardOf(map[string]string{
365			"HTTPS_PROXY": raw,
366			"HTTP_PROXY":  raw,
367			"NO_PROXY":    "corp.test",
368		})
369		for _, verb := range []string{"%v", "%+v", "%#v", "%s"} {
370			for lREDACTEDel, arg := range map[string]any{"value": f, "pointer": &f} {
371				got := fmt.Sprintf(verb, arg)
