406	func TestContainerForwardReadsOnce(t *testing.T) {
407		const (
408			first = "http://first.corp:3128"
409			other = "http://other.corp:3128"
410		)
411		got := runChild(t, "TestContainerForwardHelper",
412			map[string]string{forwardHelperEnv: "1", forwardOtherEnv: other},
413			map[string]string{"HTTPS_PROXY": first})
414	
415		parts := strings.Split(got, forwardSep)
416		if len(parts) != 3 {
417			t.Fatalf("the helper answered %q, want three readings", got)
418		}
419		wantFirst := "HTTPS_PROXY=" + first + "|https_proxy=" + first
420		if parts[0] != wantFirst {
421			t.Errorf("first ContainerForward() = %q, want %q", parts[0], wantFirst)
422		}
423		if parts[1] != parts[0] {
424			t.Errorf("ContainerForward() read the environment again: %q, then %q", parts[0], parts[1])
425		}
426		// Control: the environment did change, so only the cache explains parts[1].
427		wantFresh := "HTTPS_PROXY=" + other + "|https_proxy=" + other
428		if parts[2] != wantFresh {
429			t.Errorf("control reading = %q, want %q (the helper did not change its environment)", parts[2], wantFresh)
430		}
431	}
