2	
3	import (
4		"net"
5		"net/netip"
6		"net/url"
7		"os"
8		"regexp"
9		"strings"
10		"unicode"
11		"unicode/utf8"
12	)
13	
14	// DecisionKind says what the proxy environment variables mean for one URL.
15	type DecisionKind int
16	
17	const (
18		// DecisionNone: no variable is set for this URL's scheme. It is the zero
19		// value, so an unfilled Decision reads as "no proxy".
20		DecisionNone DecisionKind = iota
21		// DecisionProxied: a proxy carries this URL.
22		DecisionProxied
23		// DecisionExcluded: a valid variable is set and NO_PROXY names the target.
24		DecisionExcluded
25		// DecisionLoopback: a valid variable is set, but Go never proxies
26		// localhost or a loopback address.
27		DecisionLoopback
28		// DecisionInvalid: the variable is set and is not a usable proxy URL.
29		DecisionInvalid
30	)
31	
32	// Decision is what Describe found out about one URL. It carries no credential:
33	// Proxy is Display's output and an invalid value is named by its variable only.
34	type Decision struct {
35		Kind DecisionKind
36		// Variable is the name of the variable read for the URL's scheme, with the
37		// case it was read in (HTTPS_PROXY or https_proxy); empty for None.
38		Variable string
39		// Proxy is Display(proxy) when Kind is DecisionProxied, empty otherwise.
40		Proxy string
41	}
42	
43	// Describe reports which proxy, if any, applies to u in the process
44	// environment. The answer comes from FromEnvironment, the function every
45	// DevDesk client uses; only the variable's name and validity are read here.
46	func Describe(u *url.URL) Decision {
47		return describe(u, os.Getenv, FromEnvironment)
48	}
49	
50	// describe is Describe with its inputs injected. sel is not consulted when the
51	// variables alone settle the answer (None, Invalid), so it may be nil then.
52	func describe(u *url.URL, getenv func(string) string, sel Selector) Decision {
53		var names [2]string
54		switch strings.ToLower(u.Scheme) {
55		case "https":
56			names = [2]string{"HTTPS_PROXY", "https_proxy"}
57		case "http":
58			names = [2]string{"HTTP_PROXY", "http_proxy"}
59		default:
60			return Decision{}
61		}
62		name, value := firstNonEmpty(names, getenv)
63		if name == "" {
64			return Decision{}
65		}
66		if !usableProxyValue(value) {
67			return Decision{Kind: DecisionInvalid, Variable: name}
68		}
69		proxy, err := sel(u)
70		if err != nil {
71			// The error text can quote the proxy URL, credentials included.
72			return Decision{Kind: DecisionInvalid, Variable: name}
73		}
74		if proxy != nil {
75			return Decision{Kind: DecisionProxied, Variable: name, Proxy: Display(proxy)}
76		}
77		// A nil proxy with a valid variable: Go skips a loopback target whatever
78		// NO_PROXY says, otherwise NO_PROXY named it.
79		if isLoopbackHost(u.Hostname()) {
80			return Decision{Kind: DecisionLoopback, Variable: name}
81		}
82		return Decision{Kind: DecisionExcluded, Variable: name}
83	}
84	
85	// firstNonEmpty returns the first of names whose value is not empty, with that
86	// value, like Go's getEnvAny: upper case first, an empty value is not defined.
87	// It returns two empty strings when none is set.
88	func firstNonEmpty(names [2]string, getenv func(string) string) (name, value string) {
89		for _, n := range names {
90			if v := getenv(n); v != "" {
91				return n, v
92			}
93		}
94		return "", ""
95	}
96	
97	// explicitScheme matches a value that starts with a URL scheme, as opposed to
98	// one that only has "://" somewhere in its path or query.
99	var explicitScheme = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]*://`)
100	
101	// usableProxyValue follows Go's parseProxy (url.Parse, then a retry with
102	// "http://" in front for a value without a scheme) and is stricter on three
103	// points, because Go ignores an unusable value and FromEnvironment alone
104	// cannot tell it from "no proxy":
105	//   - the host must not be empty;
106	//   - a value holding "@" must end up with userinfo, otherwise the credential
107	//     was mangled (an unescaped "/", "?" or "#" before the "@") and the text
108	//     before it became the host;
109	//   - the host must be printable UTF-8, since it ends up on screen.
110	func usableProxyValue(value string) bool {
111		_, ok := parseProxyValue(value)
112		return ok
113	}
114	
115	// parseProxyValue is the parsing behind usableProxyValue: it returns the URL
116	// the value stands for, and false when the value is not usable.
117	func parseProxyValue(value string) (*url.URL, bool) {
118		explicit := explicitScheme.MatchString(value)
119		u, err := url.Parse(value)
120		switch {
121		case err != nil && explicit:
122			return nil, false
123		case err == nil && u.Scheme != "" && u.Host != "":
124			// Parsed as written.
125		case err == nil && explicit:
126			// An explicit scheme with no host, such as "http://".
127			return nil, false
128		default:
129			u, err = url.Parse("http://" + value)
130			if err != nil {
131				return nil, false
132			}
133		}
134		if u.Host == "" || (u.User == nil && strings.Contains(value, "@")) {
135			return nil, false
136		}
137		return u, isPrintable(u.Host)
138	}
139	
140	// isPrintable reports whether s is valid UTF-8 made of printable runes only.
141	func isPrintable(s string) bool {
142		if !utf8.ValidString(s) {
143			return false
144		}
145		for _, r := range s {
146			if !unicode.IsPrint(r) {
147				return false
148			}
149		}
150		return true
151	}
152	
153	// isLoopbackHost reports whether host is localhost or a loopback address.
154	func isLoopbackHost(host string) bool {
155		if strings.EqualFold(host, "localhost") {
156			return true
157		}
158		addr, err := netip.ParseAddr(host)
159		return err == nil && addr.Unmap().IsLoopback()
160	}
161	
162	// defaultPorts are the ports Display shows when the URL names none.
163	var defaultPorts = map[string]string{
164		"http":    "80",
165		"https":   "443",
166		"socks5":  "1080",
167		"socks5h": "1080",
168	}
169	
170	// Display renders a proxy URL as scheme://host:port and nothing else: never
171	// userinfo, path, query, fragment or IPv6 zone. It is the only way a proxy leaves this
172	// package for the screen. A scheme with no known default port shows no port
173	// unless the URL names one. Display(nil) is empty.
174	func Display(proxy *url.URL) string {
175		if proxy == nil {
176			return ""
177		}
178		port := proxy.Port()
179		if port == "" {
180			port = defaultPorts[strings.ToLower(proxy.Scheme)]
181		}
182		// The zone of a link-local address can be any text: drop it.
183		host, _, _ := strings.Cut(proxy.Hostname(), "%")
184		if port != "" {
185			host = net.JoinHostPort(host, port)
186		} else if strings.Contains(host, ":") {
187			host = "[" + host + "]"
188		}
189		return proxy.Scheme + "://" + host
190	}
