170	// Display renders a proxy URL as scheme://host:port and nothing else: never
171	// userinfo, path, query, fragment or IPv6 zone. It is the only way a proxy leaves this
172	// package for the screen. A scheme with no known default port shows no port
173	// unless the URL names one. Display(nil) is empty.
174	func Display(proxy *url.URL) string {
175		if proxy == nil {
176			return ""
177		}
178		port := proxy.Port()
179		if port == "" {
180			port = defaultPorts[strings.ToLower(proxy.Scheme)]
181		}
182		// The zone of a link-local address can be any text: drop it.
183		host, _, _ := strings.Cut(proxy.Hostname(), "%")
184		if port != "" {
185			host = net.JoinHostPort(host, port)
186		} else if strings.Contains(host, ":") {
187			host = "[" + host + "]"
188		}
189		return proxy.Scheme + "://" + host
190	}
